function mdl = build_pendulum_pip_model(out_dir, simulate)
%BUILD_PENDULUM_PIP_MODEL Create adapt_ctrl_sys_id_pendulum_pip.slx: digital PI-P cascade on the nonlinear pendulum.
%   mdl = BUILD_PENDULUM_PIP_MODEL(out_dir, simulate)
%
%   Reference profile (MATLAB Function) --ZOH 10 ms--> Digital PI-P cascade
%   (+ gravity feedforward) -> 0..100 % -> nonlinear pendulum with rotor lag,
%   thrust-dependent damping and air drag -> phi, phid --ZOH--> controller.
%
%   All coefficients live in the model workspace; the model is generated by
%   this script, so no binary model files are kept in the repository.

if nargin < 1 || isempty(out_dir)
    out_dir = pwd;
end
if nargin < 2
    simulate = true;
end
p = acsi_params();
g = p.geometry;
cal = p.calibrated;
c = acsi_pendulum_coeffs(cal, g);
lin = acsi_pendulum_linearize(cal, g, deg2rad(p.design.phi_op_deg));
lin.b = lin.b * 180 / pi;
d = acsi_place_pid(lin, p.design.omega, p.design.zeta, p.design.alpha, p.design.ts);

mdl = 'adapt_ctrl_sys_id_pendulum_pip';
if bdIsLoaded(mdl)
    close_system(mdl, 0);
end
new_system(mdl);
set_param(mdl, 'StopTime', '120', 'Solver', 'ode45', 'MaxStep', '2e-3');
ws = get_param(mdl, 'ModelWorkspace');
values = struct('J', c.J, 'a0', c.a0, 'a1', cal.viscous, 'b0', c.b0, 'd_u', cal.thrust_damping, ...
                'c_drag', cal.drag, 'tau_r', cal.rotor_tau, 'q0_PI', d.q0_pi, 'q1_PI', d.q1_pi, 'q0_P', d.q0_p, ...
                'Ts', d.ts);
names = fieldnames(values);
for i = 1:numel(names)
    assignin(ws, names{i}, values.(names{i}));
end

%% Top level
place(mdl, 'Reference', 'built-in/Subsystem', [30, 60], 'Size', [90, 50]);
place(mdl, 'zoh ref', 'simulink/Discrete/Zero-Order Hold', [160, 70], 'SampleTime', 'Ts');
place(mdl, 'zoh phi', 'simulink/Discrete/Zero-Order Hold', [160, 160], 'SampleTime', 'Ts');
place(mdl, 'zoh phid', 'simulink/Discrete/Zero-Order Hold', [160, 230], 'SampleTime', 'Ts');
place(mdl, 'Digital PI-P', 'built-in/Subsystem', [250, 60], 'Size', [110, 200]);
place(mdl, 'Gravity feedforward', 'built-in/Subsystem', [250, 300], 'Size', [110, 50]);
place(mdl, 'Add feedforward', 'simulink/Math Operations/Sum', [400, 150], 'Inputs', '|++', 'IconShape', 'round');
place(mdl, 'Rotor limit', 'simulink/Discontinuities/Saturation', [460, 145], 'UpperLimit', '100', 'LowerLimit', '0');
place(mdl, 'Pendulum', 'built-in/Subsystem', [560, 130], 'Size', [110, 80]);
place(mdl, 'log ref', 'simulink/Sinks/To Workspace', [250, 0], 'VariableName', 'ref', 'SaveFormat', 'Timeseries', ...
      'SampleTime', 'Ts');
place(mdl, 'log u', 'simulink/Sinks/To Workspace', [560, 40], 'VariableName', 'u', 'SaveFormat', 'Timeseries', ...
      'SampleTime', 'Ts');
place(mdl, 'log phi', 'simulink/Sinks/To Workspace', [740, 120], 'VariableName', 'phi', 'SaveFormat', 'Timeseries', ...
      'SampleTime', 'Ts');

%% Reference profile
sys = [mdl '/Reference'];
place(sys, 'Clock', 'simulink/Sources/Clock', [20, 40]);
place(sys, 'reference profile', 'simulink/User-Defined Functions/MATLAB Function', [100, 30], 'Size', [80, 50]);
place(sys, 'phi_ref_deg', 'built-in/Outport', [230, 45]);
chart = find(sfroot, '-isa', 'Stateflow.EMChart', 'Path', [sys '/reference profile']);
script = {'function r = phi_ref(t)'
          '% rest, 2 deg/s ramp to 40 deg, then plateaus at 40, 30, 50 and 40 deg'
          'if t < 5'
          '    r = 0;'
          'elseif t < 25'
          '    r = 2 * (t - 5);'
          'elseif t < 40'
          '    r = 40;'
          'elseif t < 65'
          '    r = 30;'
          'elseif t < 90'
          '    r = 50;'
          'else'
          '    r = 40;'
          'end'};
chart.Script = strjoin(script.', newline);
wire(sys, 'Clock/1', 'reference profile/1');
wire(sys, 'reference profile/1', 'phi_ref_deg/1');

%% Digital PI-P cascade:  u_PI(k) = u_PI(k-1) + q0_PI e(k) + q1_PI e(k-1),  u(k) = q0_P (u_PI(k) - phid(k))
sys = [mdl '/Digital PI-P'];
place(sys, 'ref', 'built-in/Inport', [20, 40]);
place(sys, 'phi', 'built-in/Inport', [20, 120]);
place(sys, 'phid', 'built-in/Inport', [20, 260]);
place(sys, 'e', 'simulink/Math Operations/Sum', [90, 45], 'Inputs', '|+-', 'IconShape', 'round');
place(sys, 'q0_PI', 'simulink/Math Operations/Gain', [160, 40], 'Gain', 'q0_PI');
place(sys, 'e(k-1)', 'simulink/Discrete/Unit Delay', [160, 110], 'SampleTime', 'Ts');
place(sys, 'q1_PI', 'simulink/Math Operations/Gain', [240, 110], 'Gain', 'q1_PI');
place(sys, 'u_PI', 'simulink/Math Operations/Sum', [320, 60], 'Inputs', '+++');
place(sys, 'u_PI(k-1)', 'simulink/Discrete/Unit Delay', [320, 180], 'SampleTime', 'Ts', 'Orientation', 'left');
place(sys, 'rate error', 'simulink/Math Operations/Sum', [420, 65], 'Inputs', '|+-', 'IconShape', 'round');
place(sys, 'q0_P', 'simulink/Math Operations/Gain', [490, 60], 'Gain', 'q0_P');
place(sys, 'u', 'built-in/Outport', [580, 65]);
wire(sys, 'ref/1', 'e/1');
wire(sys, 'phi/1', 'e/2');
wire(sys, 'e/1', 'q0_PI/1');
wire(sys, 'e/1', 'e(k-1)/1');
wire(sys, 'e(k-1)/1', 'q1_PI/1');
wire(sys, 'q0_PI/1', 'u_PI/1');
wire(sys, 'q1_PI/1', 'u_PI/2');
wire(sys, 'u_PI(k-1)/1', 'u_PI/3');
wire(sys, 'u_PI/1', 'u_PI(k-1)/1');
wire(sys, 'u_PI/1', 'rate error/1');
wire(sys, 'phid/1', 'rate error/2');
wire(sys, 'rate error/1', 'q0_P/1');
wire(sys, 'q0_P/1', 'u/1');

%% Gravity feedforward u_ff = max(0, a0 sin(r) / b0)
sys = [mdl '/Gravity feedforward'];
place(sys, 'ref', 'built-in/Inport', [20, 40]);
place(sys, 'deg to rad', 'simulink/Math Operations/Gain', [80, 35], 'Gain', 'pi/180');
place(sys, 'sin', 'simulink/Math Operations/Trigonometric Function', [150, 35], 'Operator', 'sin');
place(sys, 'a0 over b0', 'simulink/Math Operations/Gain', [220, 35], 'Gain', 'a0/b0');
place(sys, 'no negative thrust', 'simulink/Discontinuities/Saturation', [290, 35], 'UpperLimit', 'inf', ...
      'LowerLimit', '0');
place(sys, 'u_ff', 'built-in/Outport', [370, 40]);
wire(sys, 'ref/1', 'deg to rad/1');
wire(sys, 'deg to rad/1', 'sin/1');
wire(sys, 'sin/1', 'a0 over b0/1');
wire(sys, 'a0 over b0/1', 'no negative thrust/1');
wire(sys, 'no negative thrust/1', 'u_ff/1');

%% Nonlinear pendulum:  J phi'' = b0 w - a0 sin(phi) - (a1 + d_u w) phid - c phid |phid|,  tau_r w' = u - w
sys = [mdl '/Pendulum'];
place(sys, 'u', 'built-in/Inport', [20, 50]);
place(sys, 'rotor lag', 'simulink/Continuous/Transfer Fcn', [80, 40], 'Numerator', '1', ...
      'Denominator', '[tau_r 1]', 'Size', [60, 40]);
place(sys, 'b0', 'simulink/Math Operations/Gain', [180, 45], 'Gain', 'b0');
place(sys, 'torque sum', 'simulink/Math Operations/Sum', [260, 40], 'Inputs', '+----', 'Size', [30, 110]);
place(sys, 'inverse J', 'simulink/Math Operations/Gain', [320, 80], 'Gain', '1/J');
place(sys, 'integrate phidd', 'simulink/Continuous/Integrator', [390, 80]);
place(sys, 'integrate phid', 'simulink/Continuous/Integrator', [470, 80]);
place(sys, 'sin', 'simulink/Math Operations/Trigonometric Function', [470, 170], 'Operator', 'sin', ...
      'Orientation', 'left');
place(sys, 'a0', 'simulink/Math Operations/Gain', [390, 170], 'Gain', 'a0', 'Orientation', 'left');
place(sys, 'a1', 'simulink/Math Operations/Gain', [390, 230], 'Gain', 'a1', 'Orientation', 'left');
place(sys, 'w times phid', 'simulink/Math Operations/Product', [470, 280], 'Orientation', 'left');
place(sys, 'd_u', 'simulink/Math Operations/Gain', [390, 280], 'Gain', 'd_u', 'Orientation', 'left');
place(sys, 'abs phid', 'simulink/Math Operations/Abs', [540, 340], 'Orientation', 'left');
place(sys, 'phid times abs phid', 'simulink/Math Operations/Product', [470, 340], 'Orientation', 'left');
place(sys, 'c_drag', 'simulink/Math Operations/Gain', [390, 340], 'Gain', 'c_drag', 'Orientation', 'left');
place(sys, 'to deg', 'simulink/Math Operations/Gain', [560, 80], 'Gain', '180/pi');
place(sys, 'rate to deg', 'simulink/Math Operations/Gain', [560, 20], 'Gain', '180/pi');
place(sys, 'phi_deg', 'built-in/Outport', [640, 85]);
place(sys, 'phid_deg', 'built-in/Outport', [640, 25]);
wire(sys, 'u/1', 'rotor lag/1');
wire(sys, 'rotor lag/1', 'b0/1');
wire(sys, 'b0/1', 'torque sum/1');
wire(sys, 'a0/1', 'torque sum/2');
wire(sys, 'a1/1', 'torque sum/3');
wire(sys, 'd_u/1', 'torque sum/4');
wire(sys, 'c_drag/1', 'torque sum/5');
wire(sys, 'torque sum/1', 'inverse J/1');
wire(sys, 'inverse J/1', 'integrate phidd/1');
wire(sys, 'integrate phidd/1', 'integrate phid/1');
wire(sys, 'integrate phid/1', 'sin/1');
wire(sys, 'sin/1', 'a0/1');
wire(sys, 'integrate phidd/1', 'a1/1');
wire(sys, 'rotor lag/1', 'w times phid/1');
wire(sys, 'integrate phidd/1', 'w times phid/2');
wire(sys, 'w times phid/1', 'd_u/1');
wire(sys, 'integrate phidd/1', 'abs phid/1');
wire(sys, 'integrate phidd/1', 'phid times abs phid/1');
wire(sys, 'abs phid/1', 'phid times abs phid/2');
wire(sys, 'phid times abs phid/1', 'c_drag/1');
wire(sys, 'integrate phid/1', 'to deg/1');
wire(sys, 'integrate phidd/1', 'rate to deg/1');
wire(sys, 'to deg/1', 'phi_deg/1');
wire(sys, 'rate to deg/1', 'phid_deg/1');

%% Top-level wiring
wire(mdl, 'Reference/1', 'zoh ref/1');
wire(mdl, 'Reference/1', 'log ref/1');
wire(mdl, 'zoh ref/1', 'Digital PI-P/1');
wire(mdl, 'zoh ref/1', 'Gravity feedforward/1');
wire(mdl, 'zoh phi/1', 'Digital PI-P/2');
wire(mdl, 'zoh phid/1', 'Digital PI-P/3');
wire(mdl, 'Digital PI-P/1', 'Add feedforward/1');
wire(mdl, 'Gravity feedforward/1', 'Add feedforward/2');
wire(mdl, 'Add feedforward/1', 'Rotor limit/1');
wire(mdl, 'Rotor limit/1', 'Pendulum/1');
wire(mdl, 'Rotor limit/1', 'log u/1');
wire(mdl, 'Pendulum/1', 'zoh phi/1');
wire(mdl, 'Pendulum/1', 'log phi/1');
wire(mdl, 'Pendulum/2', 'zoh phid/1');

file = fullfile(out_dir, [mdl '.slx']);
save_system(mdl, file);
fprintf('saved %s (q0_PI = %.4f, q1_PI = %.4f, q0_P = %.4f)\n', file, d.q0_pi, d.q1_pi, d.q0_p);

if simulate
    out = sim(mdl);
    window = out.phi.Time >= 30 & out.phi.Time <= 100;
    r = interp1(out.ref.Time, out.ref.Data, out.phi.Time);
    fprintf('J_e = %.3f deg^2 (30-100 s)\n', mean((r(window) - out.phi.Data(window)).^2));
    figure('Name', mdl);
    tiledlayout(2, 1, 'TileSpacing', 'compact');
    nexttile;
    plot(out.ref.Time, out.ref.Data, 'k--', out.phi.Time, out.phi.Data, 'LineWidth', 1.3);
    grid on;
    ylabel('\phi [deg]');
    nexttile;
    plot(out.u.Time, out.u.Data, 'LineWidth', 1.1);
    grid on;
    xlabel('t [s]');
    ylabel('u [%]');
end
end

function place(sys, name, library, xy, varargin)
% Add a block at the top-left corner xy; an optional 'Size', [w h] pair sets its size.
size_wh = [40, 30];
k = find(strcmp(varargin(1:2:end), 'Size'), 1);
if ~isempty(k)
    size_wh = varargin{2 * k};
    varargin(2 * k - 1:2 * k) = [];
end
add_block(library, [sys '/' name], 'Position', [xy, xy + size_wh], varargin{:});
end

function wire(sys, from, to)
add_line(sys, from, to, 'autorouting', 'on');
end
